```javascript
import {
  Group, Mesh, Shape, ShapeGeometry, CircleGeometry, CylinderGeometry,
  MeshStandardNodeMaterial, MeshPhysicalNodeMaterial,
  Color, Vector2, Vector3, DirectionalLight, AmbientLight
} from 'three/webgpu';
import { uv, vec3, vec4, mix, uniform, time, add, mul, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Parse three card data groups
  const cardData = [];
  const textData = [];
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (!item || !item.text) continue;
    if (item.role === 'icon-glyph' || item.typography?.fontWeight === 700) {
      textData.push({ type: 'icon', text: item.text });
    } else if (item.role === 'card-title' || item.typography?.fontSize === 20) {
      textData.push({ type: 'title', text: item.text });
    } else if (item.role === 'body' || item.typography?.fontSize === 13) {
      textData.push({ type: 'body', text: item.text });
    }
  }
  for (let i = 0; i < 3; i++) {
    cardData.push({
      icon: textData[i * 3]?.text ?? '0' + (i + 1),
      title: textData[i * 3 + 1]?.text ?? '',
      body: textData[i * 3 + 2]?.text ?? ''
    });
  }

  // Constants - adjusted for proper filling with dark background
  const cardW = 1.5;
  const cardH = 1.9;
  const cornerRadius = 0.06;
  const borderWidth = 0.006;
  const gap = 0.25;
  const totalWidth = cardW * 3 + gap * 2;
  const startX = -totalWidth / 2 + cardW / 2;

  // Colors from spec - EXACT
  const bgColor = new Color('#0b0b10');
  const surfaceColor = new Color('#16161d');
  const inkColor = new Color('#16161d');
  const paperColor = new Color('#e8ecf2');
  const accentColor = new Color('#ff2a38');

  // Create backdrop - MUST FILL FRAME not leave white void
  const backdropGeo = new ShapeGeometry(new Shape()
    .moveTo(-3.5, -3)
    .lineTo(3.5, -3)
    .lineTo(3.5, 2.5)
    .lineTo(-3.5, 2.5)
    .closePath());
  const topBgColor = uniform(new Color('#191921'));
  const bottomBgColor = uniform(new Color('#121218'));
  const backdropMat = new MeshStandardNodeMaterial({
    colorNode: mix(topBgColor, bottomBgColor, uv().y),
    roughness: 1,
    metalness: 0,
    side: 2
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;

  // Border material
  const borderMat = new MeshStandardNodeMaterial({
    color: new Color('#26262f'),
    roughness: 0.6,
    metalness: 0.25,
    clearcoat: 0.15,
    transparent: true,
    opacityNode: uniform(1)
  });

  // Disc geometry
  const discGeo = new CylinderGeometry(0.2, 0.2, 0.05, 32);
  const discMat = new MeshPhysicalNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    anisotropy: 0.6,
    color: surfaceColor,
    transparent: true,
    opacityNode: uniform(1)
  });

  // Icon glyph material with emissive
  const iconMat = new MeshPhysicalNodeMaterial({
    color: accentColor,
    emissive: accentColor,
    emissiveIntensity: 1.6,
    transparent: true,
    opacityNode: uniform(1)
  });

  // Contact shadow
  const shadowOpacity = uniform(0.5);
  const shadowScale = uniform(1);
  const shadowGeo = new CircleGeometry(0.8, 32);
  const shadowMat = new MeshStandardNodeMaterial({
    color: new Color(0, 0, 0),
    transparent: true,
    opacityNode: shadowOpacity,
    roughness: 1,
    metalness: 0
  });

  // Rounded rect helper
  function createRoundedRectShape(w, h, r) {
    const shape = new Shape();
    shape.moveTo(-w / 2 + r, -h / 2);
    shape.lineTo(w / 2 - r, -h / 2);
    shape.quadraticCurveTo(w / 2, -h / 2, w / 2, -h / 2 + r);
    shape.lineTo(w / 2, h / 2 - r);
    shape.quadraticCurveTo(w / 2, h / 2, w / 2 - r, h / 2);
    shape.lineTo(-w / 2 + r, h / 2);
    shape.quadraticCurveTo(-w / 2, h / 2, -w / 2, h / 2 - r);
    shape.lineTo(-w / 2, -h / 2 + r);
    shape.quadraticCurveTo(-w / 2, -h / 2, -w / 2 + r, -h / 2);
    return shape;
  }

  // Gradient card material
  const topCardColor = uniform(new Color('#191921'));
  const bottomCardColor = uniform(new Color('#121218'));
  const gradientNode = mix(topCardColor, bottomCardColor, uv().y);
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.25,
    clearcoat: 0.15,
    colorNode: gradientNode,
    transparent: true,
    opacityNode: uniform(1)
  });

  // Geometries for cards
  const borderShape = createRoundedRectShape(cardW + borderWidth * 2, cardH + borderWidth * 2, cornerRadius + borderWidth);
  const borderGeo = new ShapeGeometry(borderShape);
  const cardShape = createRoundedRectShape(cardW, cardH, cornerRadius);
  const cardGeo = new ShapeGeometry(cardShape);

  // Fix disk geometry - ensure proper UVs for icon placement
  const iconDiskGeo = new CylinderGeometry(0.15, 0.15, 0.05, 24);

  // Root group
  const root = new Group();
  root.add(backdrop);

  // Ambient fill - prevents dead black areas
  const ambient = new AmbientLight(0x404055, 0.6);
  root.add(ambient);

  // Key light upper-left
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1.5, 1.5, 3);
  root.add(keyLight);

  // Rim light lower-right
  const rimLight = new DirectionalLight(0xffffff, 0.6);
  rimLight.position.set(-1.5, -1.5, 2.5);
  root.add(rimLight);

  // Storage for cleanup
  const cleanupFns = [];
  const timelines = [];
  const entranceTL = gsap.timeline();

  // Card creation
  cardData.forEach((data, index) => {
    const cardGroup = new Group();
    const xPos = startX + index * (cardW + gap);
    cardGroup.position.set(xPos, 0, 0);

    // Per-card opacity
    const cardOpacity = uniform(0);
    const cloneMat = (mat) => {
      const clone = mat.clone();
      clone.opacityNode = cardOpacity;
      clone.transparent = true;
      return clone;
    };

    // Border
    const borderMesh = new Mesh(borderGeo, cloneMat(borderMat));
    borderMesh.position.z = -0.005;
    cardGroup.add(borderMesh);

    // Card face
    const cardMesh = new Mesh(cardGeo, cloneMat(cardMat));
    cardGroup.add(cardMesh);

    // Contact shadow
    const shadowMesh = new Mesh(shadowGeo, shadowMat.clone());
    shadowMesh.position.z = -0.015;
    cardGroup.add(shadowMesh);

    // Icon disc seat
    const disc = new Mesh(iconDiskGeo, cloneMat(discMat));
    disc.position.set(0, 0.45, 0.01);
    cardGroup.add(disc);

    // Icon glyph with proper accent color
    const iconText = ctx.fontAtlas.createText(data.icon, {
      fontSize: 20,
      color: '#ff2a38',
      align: 'center'
    });
    iconText.traverse((child) => {
      if (child.isMesh && child.material) {
        child.material = cloneMat(iconMat);
      }
    });
    iconText.position.set(0, 0.45, 0.02);
    cardGroup.add(iconText);

    // Title with paper color
    const titleText = ctx.fontAtlas.createText(data.title, {
      fontSize: 20,
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: 200
    });
    titleText.position.set(0, -0.05, 0.01);
    cardGroup.add(titleText);

    // Body text
    const bodyText = ctx.fontAtlas.createText(data.body, {
      fontSize: 13,
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: 200
    });
    bodyText.position.set(0, -0.35, 0.01);
    cardGroup.add(bodyText);

    // Store references for hover
    cardGroup.userData = {
      shadowMesh,
      iconText,
      disc,
      cardOpacity,
      cardMesh
    };

    // Hover handlers
    cardGroup.userData.handlers = {
      pointerenter: () => {
        if (cardGroup.userData.hoverTL) cardGroup.userData.hoverTL.kill();
        const tl = gsap.timeline({ paused: true });
        tl.to(cardGroup.position, {
          y: 0.06,
          z: 0.12,
          duration: 0.18,
          ease: 'power2.out'
        }, 0);
        tl.to(shadowMesh.scale, {
          x: 1.3,
          y: 1.3,
          duration: 0.18,
          ease: 'power2.out'
        }, 0);
        tl.to(shadowOpacity, {
          value: 0.6,
          duration: 0.18,
          ease: 'power2.out'
        }, 0);
        const iconMatCloned = iconText.children[0]?.material;
        if (iconMatCloned) {
          tl.to(iconMatCloned, {
            emissiveIntensity: 2.2,
            duration: 0.18,
            ease: 'power2.out'
          }, 0);
        }
        tl.play();
        cardGroup.userData.hoverTL = tl;
        timelines.push(tl);
      },
      pointerleave: () => {
        if (cardGroup.userData.hoverTL) cardGroup.userData.hoverTL.kill();
        const tl = gsap.timeline({ paused: true });
        tl.to(cardGroup.position, {
          y: 0,
          z: 0,
          duration: 0.18,
          ease: 'power2.out'
        }, 0);
        tl.to(shadowMesh.scale, {
          x: 1,
          y: 1,
          duration: 0.18,
          ease: 'power2.out'
        }, 0);
        tl.to(shadowOpacity, {
          value: 0.5,
          duration: 0.18,
          ease: 'power2.out'
        }, 0);
        const iconMatCloned = iconText.children[0]?.material;
        if (iconMatCloned) {
          tl.to(iconMatCloned, {
            emissiveIntensity: 1.6,
            duration: 0.18,
            ease: 'power2.out'
          }, 0);
        }
        tl.play();
        cardGroup.userData.hoverTL = tl;
        timelines.push(tl);
      }
    };

    // Entrance: fade-up with stagger
    entranceTL.to(cardOpacity, {
      value: 1,
      duration: 0.5,
      ease: 'power2.out'
    }, index * 0.08);
    entranceTL.fromTo(cardGroup.position, {
      y: cardGroup.position.y + 0.2
    }, {
      y: cardGroup.position.y,
      duration: 0.5,
      ease: 'power2.out'
    }, index * 0.08);

    root.add(cardGroup);
  });

  timelines.push(entranceTL);
  entranceTL.play();

  // Event handlers root level
  root.userData.handlers = {};

  // Cleanup
  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    root.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });
    while (root.children.length) {
      root.remove(root.children[0]);
    }
  };

  return root;
}
